import { Component, Event, EventEmitter, Host, Prop, h } from '@stencil/core';

/**
 * @slot default - default slot for the text of the text
 */
@Component({
  tag: 'groupui-text',
  styleUrl: 'text.scss',
  shadow: true,
})
export class Text {
  /**
   * application type is product by default. Changes the application type to marketing.
   */
  @Prop({ reflect: true }) readonly marketing: boolean;

  /**
   * sets the font size of the text
   */
  @Prop({ reflect: true }) readonly size: 'body-1' | 'body-2' | 'caption' | 'label';

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly weight;
  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly fontVariant;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        <slot></slot>
      </Host>
    );
  }
}
